/* 📚 /learn — the roadmap page */

/* ============================================================
   JUMPING TO AN ANCHOR ON THIS SITE
   ------------------------------------------------------------
   Every obvious approach silently does nothing, and it took a
   while to work out why, so: the cause is `scroll-behavior:
   smooth` on <html> (global.js), NOT overflow:clip as the note
   in StackEdu.js assumes. The smooth animation is started and
   then interrupted — by a re-render, by the floating assistant's
   own scrollTo(0), by anything — and the page lands back at the
   top. Measured: an assignment settles at 15px instead of 5668.

   Forcing behaviour to `auto` for the duration of the assignment
   lands instantly and sticks. Verified in the browser.

   window.scrollTo() and scrollIntoView() stay unusable here, so
   this is also why every in-page link on this page goes through
   an onClick rather than relying on the browser's own fragment
   navigation.
   ============================================================ */
function jumpTo(id) {
  const el = document.getElementById(id);
  if (!el) return;
  const root = document.documentElement;
  const previous = root.style.scrollBehavior;
  root.style.scrollBehavior = "auto";
  root.scrollTop = Math.max(
    el.getBoundingClientRect().top + root.scrollTop - 120,
    0
  );
  root.style.scrollBehavior = previous;
  window.history.replaceState(null, "", `#${id}`);
}

/** Anchor click → our own jump. Keeps the href real for copy-link and SEO. */
function anchorJump(id) {
  return (event) => {
    event.preventDefault();
    jumpTo(id);
  };
}

const TYPE_LABEL = {
  video: "Video",
  article: "Article",
  paper: "Paper",
  repo: "Code",
  docs: "Docs",
  course: "Course",
  channel: "Channel",
  service: "Paid service",
};

const FORMAT_OF = {
  video: "watch",
  channel: "watch",
  course: "watch",
  article: "read",
  paper: "read",
  docs: "read",
  repo: "hands-on",
  service: "read",
};

function Counter({ value, label, suffix }) {
  return (
    <div className="lrn-counter">
      <span className="lrn-counter-n">
        {value}
        {suffix}
      </span>
      <span className="lrn-counter-l">{label}</span>
    </div>
  );
}

/** The argument of the page, drawn once. */
function Spine() {
  return (
    <ol className="lrn-spine" aria-label="The order these things go in">
      {spine.map((s, i) => (
        <li key={s} style={{ "--i": i }}>
          <span className="lrn-spine-n">{i + 1}</span>
          <span className="lrn-spine-t">{s}</span>
        </li>
      ))}
    </ol>
  );
}

function Resource({ r }) {
  const [openSegment, setOpenSegment] = useState(null);

  return (
    <div className={`lrn-res ${r.cost === "paid" ? "paid" : ""}`}>
      <div className="lrn-res-head">
        <span className="lrn-res-type">{TYPE_LABEL[r.type] || r.type}</span>
        {r.cost === "free" ? (
          <span className="lrn-res-cost free">free</span>
        ) : (
          <span className="lrn-res-cost paid">paid</span>
        )}
        {r.hours > 0 && <span className="lrn-res-hours">{r.hours}h</span>}
        {typeof r.rating === "number" && (
          <span className="lrn-res-rating" title="My rating">
            {r.rating}/10
          </span>
        )}
      </div>

      <h4 className="lrn-res-title">
        <a href={r.url} target="_blank" rel="noopener noreferrer">
          {r.title}
        </a>
      </h4>
      <p className="lrn-res-by">{r.by}</p>

      {/* With a video, the player and the reason to watch it sit side by
          side (see .lrn-res-media). Without one, this collapses to a plain
          block and the paragraph keeps its own measure. */}
      <div className={r.youtubeId ? "lrn-res-media" : undefined}>
        {r.youtubeId && (
          <div className="lrn-res-player">
            <LiteYouTube
              id={r.youtubeId}
              title={r.title}
              by={r.by}
              start={openSegment || 0}
              key={openSegment || "start"}
            />

            {/* Segment chips — a 3½ hour talk becomes six usable slices.
                Empty until the timestamps are verified by actually watching;
                a wrong timestamp is checkable and worse than none. */}
            {r.segments && r.segments.length > 0 && (
              <div className="lrn-segments">
                {r.segments.map((seg) => (
                  <button
                    key={seg.label}
                    type="button"
                    className="lrn-seg"
                    onClick={() => setOpenSegment(seg.start)}
                  >
                    {seg.label}{" "}
                    <span className="lrn-seg-t">
                      {Math.floor(seg.start / 60)}:
                      {String(seg.start % 60).padStart(2, "0")}
                    </span>
                  </button>
                ))}
              </div>
            )}
          </div>
        )}

        <div className="lrn-res-text">
          <p className="lrn-res-why">{r.why}</p>
          {r.unverified && (
            <p className="lrn-res-flag">
              Listed, not vouched for — I haven't used this one.
            </p>
          )}
        </div>
      </div>
    </div>
  );
}

/** "Attention — how a word chooses what matters" → "Attention". */
function shortTitle(title) {
  return title.split(" — ")[0];
}

/** A stage by id, across every track — so a #hash can be recognised. */
function stageOf(id) {
  let found = null;
  tracks.forEach((t) => {
    const hit = t.stages.find((st) => st.id === id);
    if (hit) found = hit;
  });
  return found;
}

/** Every concept in a track, deduped, for the "Covers" line in its header. */
function coversOf(track) {
  const seen = [];
  track.stages.forEach((st) =>
    (st.concepts || []).forEach((c) => {
      if (!seen.includes(c)) seen.push(c);
    })
  );
  return seen;
}

/* ============================================================
   THE EXPLAINERS, OUT IN THE OPEN
   ------------------------------------------------------------
   These seven live in the Foundations prelude, which is both
   collapsed AND behind picking a path — so the one genuinely
   original thing on the page was two clicks deep and a stranger
   arriving from a search never saw it. This surfaces them where
   they cost nothing: after the choice, so it still reads as
   "pick a path", but before anything that requires having
   picked one.
   ============================================================ */
function ExplainerShowcase() {
  const basics = trackOf(PRELUDE_TRACK);
  // Attention first. It is the one that moves most and the one people
  // screenshot, and it makes the strip obviously interactive at a glance.
  const [active, setActive] = useState(2);

  if (!basics) return null;
  const stage = basics.stages[active] || basics.stages[0];
  const Viz = stage.viz ? VIZ[stage.viz] : null;

  return (
    <section className="lrn-showcase" id="explainers">
      <div className="lrn-showcase-head">
        <div>
          <h2 className="lrn-h2">Or just look at the thing</h2>
          <p className="lrn-lede">
            Seven ideas that make everything after them obvious. Move the
            sliders — no path, no sign-up, no maths. They're the Foundations
            prelude, and every path above carries them.
          </p>
        </div>
        <p className="lrn-showcase-meta">
          {basics.stages.length} explainers · {basics.hours}h if you read the
          words too
        </p>
      </div>

      <nav className="lrn-tabs" aria-label="Explainers">
        {basics.stages.map((st, i) => (
          <button
            key={st.id}
            type="button"
            className={`lrn-tab ${i === active ? "on" : ""}`}
            aria-pressed={i === active}
            onClick={() => setActive(i)}
          >
            {shortTitle(st.title)}
          </button>
        ))}
      </nav>

      <div className="lrn-showcase-body">
        <div className="lrn-showcase-viz">{Viz && <Viz key={stage.id} />}</div>

        <div className="lrn-showcase-text">
          <h3>{stage.title}</h3>
          {/* No "You'll be able to" label: every outcome is now a standalone
              sentence, and half of them already start "You can …". */}
          <p className="lrn-outcome">{stage.outcome}</p>
          {stage.concepts && (
            <ul className="lrn-concepts">
              {stage.concepts.map((c) => (
                <li key={c}>{c}</li>
              ))}
            </ul>
          )}
          {stage.checkpoint && (
            <p className="lrn-check">
              <span className="lrn-aside-k">You're done when</span>
              {stage.checkpoint}
            </p>
          )}
        </div>
      </div>
    </section>
  );
}

/* ============================================================
   A STAGE, AS A ROW
   ------------------------------------------------------------
   Shape borrowed from the Helix track pages: a number in the
   gutter, a short type chip, the title, two lines of summary,
   and a meta footer. Collapsed, a whole path reads as one
   ordered list you can scan in fifteen seconds. Open, it is the
   full stage — video, resources, build, checkpoint.

   The number is continuous across the whole path, not restarted
   per track: the ordering IS the argument of this page, and
   restarting at 1 in every track quietly undermines it.
   ============================================================ */
function Stage({ stage, track, num, done, open, onToggle, onOpen }) {
  const Viz = stage.viz ? VIZ[stage.viz] : null;
  const resCount = (stage.resources || []).length;

  const bits = [];
  if (stage.hours > 0) bits.push(`${stage.hours}h`);
  if (resCount) bits.push(`${resCount} resource${resCount === 1 ? "" : "s"}`);
  if (stage.build) bits.push("1 build");
  if (Viz) bits.push("explainer");

  return (
    <article
      className={`lrn-row ${done ? "done" : ""} ${open ? "open" : ""}`}
      id={stage.id}
      style={{ "--c": track.accent }}
    >
      <div className="lrn-row-head">
        <button
          type="button"
          className="lrn-tick"
          onClick={() => onToggle(stage.id)}
          aria-pressed={done}
          aria-label={
            done
              ? `Mark "${stage.title}" not done`
              : `Mark "${stage.title}" done`
          }
        >
          {done ? "✓" : ""}
        </button>

        <button
          type="button"
          className="lrn-row-open"
          aria-expanded={open}
          onClick={() => onOpen(stage.id)}
        >
          <span className="lrn-row-n">{String(num).padStart(2, "0")}</span>
          <span className="lrn-row-main">
            <span className="lrn-row-chip">{track.chip}</span>
            <span className="lrn-row-title">{stage.title}</span>
            <span className="lrn-row-sum">{stage.outcome}</span>
            <span className="lrn-row-meta">{bits.join(" · ")}</span>
          </span>
          <span className="lrn-row-caret" aria-hidden="true">
            ›
          </span>
        </button>

        <a
          className="lrn-anchor"
          href={`#${stage.id}`}
          aria-label="Link to this stage"
          title="Link to this stage"
          onClick={anchorJump(stage.id)}
        >
          🔗
        </a>
      </div>

      {/* Two columns on a wide screen: the teaching on the left at a
          readable measure, and the short factual bits — what it covers, how
          you know you're finished, where I used it — as a meta column on the
          right. One column below 1200px. */}
      {open && (
        <div className="lrn-stage-body">
          <div className="lrn-stage-lead">
            {Viz && (
              <div className="lrn-viz-wrap">
                <Viz />
              </div>
            )}

            {stage.note && <p className="lrn-note">{stage.note}</p>}

            {stage.resources && stage.resources.length > 0 && (
              <div className="lrn-res-list">
                {stage.resources.map((r) => (
                  <Resource key={r.url} r={r} />
                ))}
              </div>
            )}

            {stage.build && (
              <div className="lrn-build">
                <span className="lrn-build-k">Build this</span>
                <h4>{stage.build.title}</h4>
                <p>{stage.build.brief}</p>
              </div>
            )}
          </div>

          <aside className="lrn-stage-aside">
            {stage.concepts && (
              <div className="lrn-aside-block">
                <span className="lrn-aside-k">Covers</span>
                <ul className="lrn-concepts">
                  {stage.concepts.map((c) => (
                    <li key={c}>{c}</li>
                  ))}
                </ul>
              </div>
            )}

            {stage.checkpoint && (
              <div className="lrn-aside-block">
                <span className="lrn-aside-k">You're done when</span>
                <p className="lrn-check">{stage.checkpoint}</p>
              </div>
            )}

            {stage.applied && stage.applied.length > 0 && (
              <div className="lrn-aside-block">
                <span className="lrn-aside-k">I put this to work in</span>
                <div className="lrn-applied">
                  {stage.applied.map((a) => (
                    <a key={a.href} href={a.href} className="lrn-applied-link">
                      {a.label} <span aria-hidden="true">→</span>
                    </a>
                  ))}
                </div>
              </div>
            )}
          </aside>
        </div>
      )}
    </article>
  );
}

export default function LearnRoadmap({ activeTrack, theme }) {
  const history = useHistory();
  const PATHS = allPaths();

  const [progress, setProgress] = useState({});
  const [freeOnly, setFreeOnly] = useState(false);
  const [format, setFormat] = useState("all");

  // The page opens on a question, not on content. `chosen` is null until the
  // visitor answers it — either by clicking, or by arriving on /learn/ai.
  const [chosen, setChosen] = useState(() => pathById(activeTrack)?.id || null);
  const [showPrelude, setShowPrelude] = useState(false);
  // Rows are closed by default — the point of the list is that you can read
  // the whole route before committing to any one step. Opening is additive
  // rather than an accordion, because comparing two stages is a real thing
  // people do here.
  const [openStages, setOpenStages] = useState(() => new Set());

  useEffect(() => {
    setProgress(readProgress());
    // A returning reader should not be asked again. Only consult the stored
    // answer when the URL has not already made the choice.
    if (!pathById(activeTrack) && !activeTrack) {
      const remembered = readPath();
      if (remembered && pathById(remembered)) setChosen(remembered);
    }
  }, [activeTrack]);

  const onToggle = useCallback((id) => {
    setProgress((p) => toggleStage(p, id));
  }, []);

  const onOpen = useCallback((id) => {
    setOpenStages((prev) => {
      const next = new Set(prev);
      if (next.has(id)) next.delete(id);
      else next.add(id);
      return next;
    });
  }, []);

  const setAllOpen = useCallback((ids, open) => {
    setOpenStages((prev) => {
      const next = new Set(prev);
      ids.forEach((id) => (open ? next.add(id) : next.delete(id)));
      return next;
    });
  }, []);

  const path = chosen ? pathById(chosen) : null;

  // The single category being read. Null means "show the route" — the
  // overview of the whole path. This is what turns the sidebar from a
  // contents list into a navigator: it swaps what is on screen rather than
  // scrolling one enormous page.
  const current = trackOf(activeTrack) || null;

  // Everything on screen for the chosen path, in reading order: the optional
  // prelude, the path's own tracks, then the interview rail.
  const visibleTracks = path
    ? [
        ...(showPrelude && path.prelude ? [path.prelude] : []),
        ...path.tracks,
        ...(path.outro ? [path.outro] : []),
      ]
    : [];

  const doneCount = visibleTracks.reduce(
    (n, t) => n + t.stages.filter((st) => progress[st.id]).length,
    0
  );
  const totalVisible = visibleTracks.reduce((n, t) => n + t.stages.length, 0);

  // One continuous run of numbers down the whole path.
  const stageNumbers = {};
  let counter = 0;
  visibleTracks.forEach((t) =>
    t.stages.forEach((st) => {
      stageNumbers[st.id] = ++counter;
    })
  );
  const pct = totalVisible ? Math.round((doneCount / totalVisible) * 100) : 0;

  const choosePath = (id) => {
    setChosen(id);
    writePath(id);
    history.push(`/learn/${id}`);
    // The chooser is what the reader is looking at; put them at the top of
    // what they just picked rather than leaving them mid-page.
    setTimeout(() => jumpTo("path-top"), 60);
  };

  const clearPath = () => {
    setChosen(null);
    writePath(null);
    history.push("/learn");
    setTimeout(() => jumpTo("choose"), 60);
  };

  const goTrack = (id) => {
    history.push(`/learn/${id}`);
    setTimeout(() => jumpTo("path-top"), 40);
  };

  const goPath = (id) => {
    history.push(`/learn/${id}`);
    setTimeout(() => jumpTo("path-top"), 40);
  };

  useEffect(() => {
    if (!activeTrack) return;

    const asPath = pathById(activeTrack);
    if (asPath) {
      setChosen(asPath.id);
      writePath(asPath.id);
    } else if (trackOf(activeTrack)) {
      // A track URL implies a path — pick the first that contains it, unless
      // the reader has already chosen one that does.
      const owners = pathsOfTrack(activeTrack);
      setChosen((current) =>
        current && owners.some((o) => o.id === current)
          ? current
          : owners[0]?.id || readPath() || "ai"
      );
      if (activeTrack === "basics") setShowPrelude(true);
    }

    // /learn/rag#chunking has to arrive on an OPEN stage, or the jump lands
    // on a closed row and the reader sees a title where they expected content.
    // The hash also wins over the track as the scroll target — it is the more
    // specific request, and jumpTo rewrites the hash, so read it first.
    const hash = window.location.hash.replace("#", "");
    const hashIsStage = hash && !!stageOf(hash);
    if (hashIsStage) setOpenStages((prev) => new Set(prev).add(hash));

    // Everything that is not a stage hash lands on the pane header, because
    // in the shell the track heading IS the top of the pane.
    const targetId = hashIsStage ? hash : "path-top";

    // The sections below have not been laid out when this effect first runs,
    // and on a cold load the splash overlay is still up. See jumpTo() above
    // for why the jump itself has to fight the stylesheet.
    let cancelled = false;
    const yieldToUser = () => {
      cancelled = true;
    };
    window.addEventListener("wheel", yieldToUser, { passive: true });
    window.addEventListener("touchstart", yieldToUser, { passive: true });

    // Two fixed passes were not enough: the layout above the target keeps
    // moving for a while — fonts swap, the explainers mount, video posters
    // arrive, and an opened row changes height — so a jump timed at 1.2s
    // could land 1500px past the mark. Instead, re-assert until the element
    // actually sits where we asked, twice in a row, or we run out of tries.
    //
    // A retry ladder like this used to make things strictly WORSE. That was
    // before jumpTo forced scroll-behavior to auto: with smooth scrolling
    // each retry cancelled the last one's animation. Instant writes are
    // idempotent, so converging is safe. See §17 of Plan_Learning.md.
    let settled = 0;
    const timers = [];
    const step = (tries) => {
      if (cancelled || tries <= 0) return;
      const el = document.getElementById(targetId);
      if (!el) {
        timers.push(setTimeout(() => step(tries - 1), 120));
        return;
      }
      const off = el.getBoundingClientRect().top - 120;
      if (Math.abs(off) < 4) {
        if (++settled >= 2) return;
      } else {
        settled = 0;
        jumpTo(targetId);
      }
      timers.push(setTimeout(() => step(tries - 1), 120));
    };
    timers.push(setTimeout(() => step(24), 260));

    return () => {
      timers.forEach(clearTimeout);
      window.removeEventListener("wheel", yieldToUser);
      window.removeEventListener("touchstart", yieldToUser);
    };
  }, [activeTrack]);

  const visible = (r) => {
    if (freeOnly && r.cost !== "free") return false;
    if (format !== "all" && FORMAT_OF[r.type] !== format) return false;
    return true;
  };

  const reviewed = monthName(lastReviewed());

  return (
    // The theme lives in a styled-components provider, not on <body>, so the
    // page has to stamp its own hook for the light-mode token block in
    // LearnRoadmap.css to match anything.
    <main className="lrn" data-theme={theme?.name}>
      {/* The front matter — hero, the choice, the explainers, the planner —
          is the landing. Inside a category it would push the actual content
          two screens down, so it is not rendered there. */}
      {!current && (
        <>
          {/* ---------- HERO ---------- */}
          <section className="lrn-hero">
            <div className="lrn-hero-main">
              <p className="lrn-kicker">Learn</p>
              <h1 className="lrn-h1">
                The path I actually walked
                <span>— with the projects to prove each step</span>
              </h1>
              <p className="lrn-lede">
                Not the definitive roadmap. Mine. {meta.entry} Every stage ends
                in something you build, and links to the production system I
                built with it.
              </p>

              <Spine />
            </div>

            <aside className="lrn-hero-side">
              <div className="lrn-counters">
                <Counter value={PATHS.length} label="paths" />
                <Counter value={stageCount()} label="stages" />
                <Counter
                  value={totalHours()}
                  label="hours of study"
                  suffix="h"
                />
                <Counter
                  value={freeCount()}
                  label={`of ${allResources().length} free`}
                />
              </div>

              <p className="lrn-reviewed">
                Last reviewed {reviewed} · links checked by hand, not generated
              </p>
            </aside>
          </section>

          {/* ---------- THE CHOICE ----------
          This is the first thing on the page for a reason. Three different
          jobs, three different routes, and a visitor who came to build agents
          should not have to scroll past tokenisation to find out. */}
          <section className="lrn-choose" id="choose">
            <h2 className="lrn-h2">What are you here to build?</h2>
            <p className="lrn-lede">
              Pick one. You can switch at any time, and the paths share more
              than they don't.
            </p>

            <div className="lrn-choices">
              {PATHS.map((p) => {
                const done = p.tracks.reduce(
                  (n, t) => n + t.stages.filter((st) => progress[st.id]).length,
                  0
                );
                return (
                  <button
                    key={p.id}
                    type="button"
                    className={`lrn-choice ${chosen === p.id ? "on" : ""} ${
                      p.headline ? "is-headline" : ""
                    }`}
                    style={{ "--c": p.accent }}
                    onClick={() => choosePath(p.id)}
                  >
                    <span className="lrn-choice-kicker">{p.kicker}</span>
                    <span className="lrn-choice-label">{p.label}</span>
                    <span className="lrn-choice-for">{p.forWhom}</span>
                    <span className="lrn-choice-blurb">{p.blurb}</span>
                    <span className="lrn-choice-meta">
                      {p.tracks.length} tracks · {pathHours(p)}h ·{" "}
                      {pathStageCount(p)} stages
                      {done > 0 && <em> · {done} done</em>}
                    </span>
                  </button>
                );
              })}
            </div>

            <p className="lrn-choose-foot">
              Not sure?{" "}
              <a href="#plan" onClick={anchorJump("plan")}>
                Answer three questions
              </a>{" "}
              and I'll pick one for you — or start with{" "}
              <button
                type="button"
                className="lrn-inline-btn"
                onClick={() => {
                  choosePath("ai");
                  setShowPrelude(true);
                }}
              >
                the four-hour Foundations prelude
              </button>{" "}
              if none of the three sound like you yet.
            </p>
          </section>

          {/* ---------- THE EXPLAINERS ---------- */}
          <ExplainerShowcase />

          {/* ---------- PLANNER ---------- */}
          <LearnPlanner onPick={choosePath} />
        </>
      )}

      {/* Nothing below this point exists until the question is answered. */}
      {!path && !current && (
        <section className="lrn-empty">
          <p>
            Choose a path above and the whole route appears here — every stage,
            what to build, and what I used it for. Not ready to commit? The{" "}
            <button
              type="button"
              className="lrn-inline-btn"
              onClick={() => jumpTo("explainers")}
            >
              seven explainers
            </button>{" "}
            are free of all of it.
          </p>
        </section>
      )}

      {path && (
        <>
          <div
            className="lrn-pathbar"
            id="path-top"
            style={{ "--c": path.accent }}
          >
            <div>
              <p className="lrn-side-k">
                {current ? (
                  <button
                    type="button"
                    className="lrn-crumb"
                    onClick={() => goPath(path.id)}
                  >
                    ‹ {path.label}
                  </button>
                ) : (
                  "Your path"
                )}
              </p>
              <h2 className="lrn-path-title">
                {current ? current.title : path.label}
              </h2>
              <p className="lrn-path-tag">
                {current ? current.tagline : path.tagline}
              </p>
            </div>
            <div className="lrn-pathbar-side">
              <span className="lrn-path-meta">
                {pathHours(path)}h core · {doneCount}/{totalVisible} stages done
              </span>
              <button type="button" className="lrn-switch" onClick={clearPath}>
                Switch path
              </button>
            </div>
          </div>

          {/* Prelude, offered rather than imposed. Only on the overview —
              inside a track it would be a second, competing table of
              contents. */}
          {!current && path.prelude && (
            <div className="lrn-prelude">
              <button
                type="button"
                className="lrn-prelude-toggle"
                onClick={() => setShowPrelude((v) => !v)}
                aria-expanded={showPrelude}
              >
                <span className="lrn-prelude-caret" aria-hidden="true">
                  ›
                </span>
                {showPrelude ? "Hide" : "Before you start —"}{" "}
                <strong>{path.prelude.title}</strong>
                <em>
                  {path.prelude.hours}h · optional ·{" "}
                  {path.prelude.stages.length} visual explainers
                </em>
              </button>
              {!showPrelude && (
                <p className="lrn-prelude-note">{path.prelude.blurb}</p>
              )}
            </div>
          )}

          {/* ================= OVERVIEW: the route, one row per category =====
              Helix's /tracks grid. You land here, you see the whole shape of
              the path, and you go into ONE category — rather than scrolling
              past every stage of every track to reach the one you wanted. */}
          {!current && (
            <>
              <section className="lrn-overview">
                <p className="lrn-side-k">The route</p>
                <ol className="lrn-tracklist">
                  {visibleTracks.map((t, i) => {
                    const dn = t.stages.filter((st) => progress[st.id]).length;
                    const extra =
                      t.id === path.prelude?.id || t.id === path.outro?.id;
                    return (
                      <li key={t.id} style={{ "--c": t.accent }}>
                        <button
                          type="button"
                          className={`lrn-trackcard ${extra ? "extra" : ""}`}
                          onClick={() => goTrack(t.id)}
                        >
                          <span className="lrn-trackcard-n">
                            {String(i + 1).padStart(2, "0")}
                          </span>
                          <span className="lrn-trackcard-main">
                            <span className="lrn-row-chip">{t.chip}</span>
                            <span className="lrn-trackcard-title">
                              {t.title}
                            </span>
                            <span className="lrn-trackcard-tag">
                              {t.tagline}
                            </span>
                            <span className="lrn-trackcard-blurb">
                              {t.blurb}
                            </span>
                            <span className="lrn-trackcard-meta">
                              {t.hours}h · {t.stages.length} stage
                              {t.stages.length === 1 ? "" : "s"} · {dn}/
                              {t.stages.length} done
                              {extra && <em> · optional</em>}
                              {pathsOfTrack(t.id).length > 1 && (
                                <em> · shared</em>
                              )}
                            </span>
                          </span>
                          <span className="lrn-row-caret" aria-hidden="true">
                            ›
                          </span>
                        </button>
                      </li>
                    );
                  })}
                </ol>
              </section>

              <section className="lrn-end">
                <h2 className="lrn-h2">Then what?</h2>
                <p>
                  Build the capstones and you have a portfolio, not a
                  certificate: something with a published eval score, something
                  with real tools behind an approval gate, and something traced
                  well enough to debug at 2am.
                </p>
                <div className="lrn-end-links">
                  <a href="/jarvis" className="lrn-cta">
                    See the agent loop running live →
                  </a>
                  <a href="/projects" className="lrn-cta ghost">
                    The projects these built →
                  </a>
                  <a href="/contact" className="lrn-cta ghost">
                    Tell me what's missing →
                  </a>
                </div>
                <p className="lrn-foot">
                  Everything here is someone else's teaching — Karpathy,
                  LangChain, Anthropic, OpenAI, scikit-learn, fast.ai, Hello
                  Interview. I've ordered it and said what each one is for. Go
                  and watch the originals.
                </p>
              </section>
            </>
          )}

          {/* ================= ONE CATEGORY, IN THE SHELL ================== */}
          {current && (
            <>
              {/* Narrow screens get the categories as a scrolling rail,
                  because the sidebar is not there to switch them. */}
              <nav className="lrn-rail" aria-label="Categories">
                {visibleTracks.map((t) => (
                  <button
                    key={t.id}
                    type="button"
                    className={`lrn-rail-item ${
                      current.id === t.id ? "on" : ""
                    }`}
                    style={{ "--c": t.accent }}
                    onClick={() => goTrack(t.id)}
                  >
                    <span className="lrn-rail-t">{t.title}</span>
                  </button>
                ))}
              </nav>

              <div className="lrn-shell">
                <aside className="lrn-side">
                  <p className="lrn-side-k">{path.label}</p>

                  <ol className="lrn-side-list">
                    {visibleTracks.map((t) => {
                      const dn = t.stages.filter((st) => progress[st.id])
                        .length;
                      const here = current.id === t.id;
                      const extra =
                        t.id === path.prelude?.id || t.id === path.outro?.id;
                      return (
                        <li key={t.id} style={{ "--c": t.accent }}>
                          <a
                            href={`/learn/${t.id}`}
                            className={`lrn-side-item ${here ? "on" : ""} ${
                              dn === t.stages.length ? "complete" : ""
                            } ${extra ? "extra" : ""}`}
                            onClick={(event) => {
                              event.preventDefault();
                              goTrack(t.id);
                            }}
                          >
                            <span className="lrn-side-t">
                              {t.title}
                              <em>
                                {t.hours}h · {dn}/{t.stages.length}
                                {extra ? " · optional" : ""}
                              </em>
                            </span>
                          </a>

                          {/* Only the category you are in lists its stages —
                              the others would be a wall of forty links. */}
                          {here && (
                            <ul className="lrn-side-stages">
                              {t.stages.map((st) => (
                                <li key={st.id}>
                                  <a
                                    href={`#${st.id}`}
                                    className={
                                      progress[st.id] ? "done" : undefined
                                    }
                                    onClick={(event) => {
                                      event.preventDefault();
                                      setAllOpen([st.id], true);
                                      setTimeout(() => jumpTo(st.id), 30);
                                    }}
                                  >
                                    <em>
                                      {String(stageNumbers[st.id]).padStart(
                                        2,
                                        "0"
                                      )}
                                    </em>
                                    {st.title}
                                  </a>
                                </li>
                              ))}
                            </ul>
                          )}
                        </li>
                      );
                    })}
                  </ol>

                  <div className="lrn-side-block">
                    <p className="lrn-side-k">Show</p>
                    <div className="lrn-filters">
                      <button
                        type="button"
                        className={`lrn-filter ${freeOnly ? "on" : ""}`}
                        onClick={() => setFreeOnly((v) => !v)}
                      >
                        Free only
                      </button>
                      {["all", "watch", "read", "hands-on"].map((f) => (
                        <button
                          key={f}
                          type="button"
                          className={`lrn-filter ${format === f ? "on" : ""}`}
                          onClick={() => setFormat(f)}
                        >
                          {f === "all" ? "Everything" : f}
                        </button>
                      ))}
                    </div>
                  </div>

                  <div className="lrn-side-block">
                    <div className="lrn-progress">
                      <div className="lrn-progress-bar">
                        <span style={{ width: `${pct}%` }} />
                      </div>
                      <span className="lrn-progress-t">
                        {doneCount}/{totalVisible} done
                      </span>
                      {doneCount > 0 && (
                        <button
                          type="button"
                          className="lrn-reset"
                          onClick={() => setProgress(clearProgress())}
                        >
                          reset
                        </button>
                      )}
                    </div>
                  </div>
                </aside>

                <div className="lrn-main">
                  {(() => {
                    const t = current;
                    const ids = t.stages.map((st) => st.id);
                    const allOpen = ids.every((id) => openStages.has(id));
                    const i = visibleTracks.findIndex((x) => x.id === t.id);
                    const prev = visibleTracks[i - 1];
                    const next = visibleTracks[i + 1];
                    return (
                      <section
                        className={`lrn-track ${t.rail ? "is-rail" : ""} ${
                          t.headline ? "is-headline" : ""
                        }`}
                        id={`track-${t.id}`}
                        style={{ "--c": t.accent }}
                      >
                        <header className="lrn-track-head">
                          <span className="lrn-track-n">
                            {t.id === path.prelude?.id
                              ? "Prelude · optional"
                              : t.id === path.outro?.id
                              ? "After the build · optional"
                              : `Track ${path.tracks.indexOf(t) + 1} of ${
                                  path.tracks.length
                                }`}
                          </span>
                          <h2 className="lrn-h2">{t.title}</h2>
                          <p className="lrn-track-tag">{t.tagline}</p>
                          <p className="lrn-track-blurb">{t.blurb}</p>

                          {coversOf(t).length > 0 && (
                            <p className="lrn-track-covers">
                              <span>Covers</span> {coversOf(t).join(" · ")}
                            </p>
                          )}

                          <div className="lrn-track-foot">
                            <p className="lrn-track-hours">
                              ~{t.hours}h · {t.stages.length} stage
                              {t.stages.length === 1 ? "" : "s"}
                              {pathsOfTrack(t.id).length > 1 && (
                                <em> · shared with the other paths</em>
                              )}
                            </p>
                            <button
                              type="button"
                              className="lrn-track-expand"
                              onClick={() => setAllOpen(ids, !allOpen)}
                            >
                              {allOpen ? "Collapse all" : "Expand all"}
                            </button>
                          </div>
                        </header>

                        {t.stages.map((st) => {
                          const filtered = {
                            ...st,
                            resources: (st.resources || []).filter(visible),
                          };
                          return (
                            <Stage
                              key={st.id}
                              stage={filtered}
                              track={t}
                              num={stageNumbers[st.id]}
                              done={!!progress[st.id]}
                              open={openStages.has(st.id)}
                              onToggle={onToggle}
                              onOpen={onOpen}
                            />
                          );
                        })}

                        <nav className="lrn-nextprev">
                          {prev ? (
                            <button
                              type="button"
                              className="lrn-np"
                              style={{ "--c": prev.accent }}
                              onClick={() => goTrack(prev.id)}
                            >
                              <em>← Previous</em>
                              {prev.title}
                            </button>
                          ) : (
                            <span />
                          )}
                          {next ? (
                            <button
                              type="button"
                              className="lrn-np next"
                              style={{ "--c": next.accent }}
                              onClick={() => goTrack(next.id)}
                            >
                              <em>Next →</em>
                              {next.title}
                            </button>
                          ) : (
                            <button
                              type="button"
                              className="lrn-np next"
                              onClick={() => goPath(path.id)}
                            >
                              <em>Done →</em>
                              Back to the route
                            </button>
                          )}
                        </nav>
                      </section>
                    );
                  })()}
                </div>
              </div>
            </>
          )}
        </>
      )}
    </main>
  );
}
