import React, { useState } from "react";

/* ============================================================
   ▶️  LITE YOUTUBE — a facade, not an iframe
   ------------------------------------------------------------
   This page embeds seven talks. Seven real YouTube iframes would
   pull megabytes of player JavaScript on load, for videos most
   visitors will never press play on.

   So the idle state is a single JPEG and a play button. The
   iframe is only created on click — and then it is created
   already playing, so the click is not wasted.

   `start` lets a stage point at the exact minute that matters
   in a three-and-a-half-hour talk. That is the whole reason
   the segment chips exist.
   ============================================================ */

export default function LiteYouTube({ id, title, start = 0, by }) {
  const [playing, setPlaying] = useState(false);
  const [failed, setFailed] = useState(false);

  if (!id) return null;

  if (playing) {
    const src =
      `https://www.youtube-nocookie.com/embed/${id}` +
      `?autoplay=1&rel=0&modestbranding=1${start ? `&start=${start}` : ""}`;
    return (
      <div className="lyt lyt-live">
        <iframe
          src={src}
          title={title}
          allow="accelerometer; autoplay; encrypted-media; gyroscope; picture-in-picture"
          allowFullScreen
        />
      </div>
    );
  }

  return (
    <button
      type="button"
      className="lyt"
      onClick={() => setPlaying(true)}
      aria-label={`Play: ${title}`}
    >
      {!failed && (
        <img
          src={`https://i.ytimg.com/vi/${id}/hqdefault.jpg`}
          alt=""
          loading="lazy"
          onError={() => setFailed(true)}
        />
      )}
      <span className="lyt-shade" />
      <span className="lyt-play" aria-hidden="true">
        <svg viewBox="0 0 24 24" width="26" height="26">
          <path d="M8 5v14l11-7z" fill="currentColor" />
        </svg>
      </span>
      <span className="lyt-meta">
        <span className="lyt-title">{title}</span>
        {by && <span className="lyt-by">{by}</span>}
      </span>
    </button>
  );
}
