import React, { useState } from "react";
import { getApiKeys } from "../../utils/keyService";
import { allPaths, pathById } from "./learnData";

/* ============================================================
   🧭 PLAN MY PATH
   ------------------------------------------------------------
   Two tiers, and the answer always says which one it came from —
   the same rule the Jarvis page follows. A page whose whole claim
   is honesty cannot serve a canned answer under a live badge.

   · Local planner  — deterministic, instant, works offline and
                      with no API key. Picks the starting track
                      from what you already know and divides the
                      real hours in learnData by your weekly time.
   · Gemini         — same plan, but it writes the reasoning in
                      prose and can react to the free-text detail.
                      Grounded HARD: it is given the track list and
                      told it may not invent resources. The whole
                      value of this page is that every link on it
                      was chosen deliberately.

   Key comes from Firestore at runtime via keyService (config/apiKeys),
   never from env or the bundle — same as AIAssistant and ttsService.

   ⚠️  MODEL ID. gemini-2.0-flash — which AIAssistant.js and aiEngines.js
   still call — was retired by Google and now 404s with "no longer
   available, please update to models/gemini-3.6-flash". Verified against
   the live key on 2026-08-29. Those two files need the same swap; until
   they get it, every AI feature on the site that isn't this one is
   silently falling back.
   ============================================================ */

const MODEL = "gemini-3.6-flash";

const LEVELS = [
  {
    id: "new",
    label: "New to this",
    detail: "I can code, but I've barely touched models",
    skips: [],
  },
  {
    id: "used",
    label: "I've used the APIs",
    detail: "Prompts and a wrapper or two, nothing in production",
    skips: ["llms"],
  },
  {
    id: "rag",
    label: "I've shipped something",
    detail: "It works; measurement and reliability are the gap",
    skips: ["llms", "rag", "ml-core"],
  },
];

const PACES = [
  { id: 3, label: "3 h / week" },
  { id: 6, label: "6 h / week" },
  { id: 12, label: "12 h / week" },
];

/** The deterministic plan. No network, no key, always available. */
function localPlan(levelId, goalId, hoursPerWeek) {
  const level = LEVELS.find((l) => l.id === levelId) || LEVELS[0];
  const path = pathById(goalId) || pathById("ai");

  // Drop what the reader already has behind them, but never drop the last
  // track — a plan that recommends nothing is not a plan.
  const skipIds = level.skips || [];
  const kept = path.tracks.filter((t) => !skipIds.includes(t.id));
  const chosen = kept.length ? kept : path.tracks;
  const hours = chosen.reduce((s, t) => s + t.hours, 0);
  const weeks = Math.ceil(hours / hoursPerWeek);

  return {
    source: "curriculum",
    path,
    tracks: chosen,
    hours,
    weeks,
    text:
      `Take the **${path.label}** path, starting at **${chosen[0].title}**. ` +
      `That is ${hours} hours of study — about **${weeks} weeks** at ` +
      `${hoursPerWeek} h/week — plus the builds, which are where it actually sticks.` +
      (level.id === "new"
        ? ` Do the four-hour Foundations prelude first; it makes everything after it cheaper.`
        : "") +
      ` Whatever you cut, do not cut the evals track. Everyone cuts the evals track.`,
  };
}

const PROMPT_RULES = `You are helping someone plan a study path through an existing curriculum.

RULES — these are absolute:
- Recommend ONLY tracks from the list below. Do not invent courses, books, videos or links.
- Do not suggest resources from your own knowledge. The curator chose these deliberately.
- Be direct and practical. No hype, no "exciting journey", no emoji.
- 120 words maximum. Plain prose, no headings.
- Mention the realistic week count you are given, and be honest that it is study time only.`;

export default function LearnPlanner({ onPick }) {
  const [level, setLevel] = useState("used");
  const [goal, setGoal] = useState("ai");
  const [pace, setPace] = useState(6);
  const [detail, setDetail] = useState("");
  const [result, setResult] = useState(null);
  const [busy, setBusy] = useState(false);

  const run = async () => {
    const base = localPlan(level, goal, pace);
    setBusy(true);
    setResult(base); // show the deterministic answer immediately
    // Answering the planner IS choosing a path — don't make them pick twice.
    if (onPick) onPick(goal);

    try {
      const { gemini: key } = await getApiKeys();
      if (!key) return; // no key configured — the local plan stands, badged as such

      const levelLabel = LEVELS.find((l) => l.id === level).label;
      const trackList = base.tracks
        .map(
          (t) =>
            `- ${t.title} (${t.hours}h): ${t.tagline}. Covers: ${t.stages
              .map((s) => s.title)
              .join("; ")}`
        )
        .join("\n");

      const prompt = `${PROMPT_RULES}

TRACKS AVAILABLE TO RECOMMEND:
${trackList}

LEARNER: ${levelLabel}. Wants to work on ${base.path.label} (${
        base.path.kicker
      }). Has ${pace} hours a week. Total study time for these tracks is ${
        base.hours
      } hours (~${base.weeks} weeks at their pace).
${detail ? `In their own words: "${detail.slice(0, 400)}"` : ""}

Write their plan.`;

      const res = await fetch(
        `https://generativelanguage.googleapis.com/v1beta/models/${MODEL}:generateContent?key=${key}`,
        {
          method: "POST",
          headers: { "Content-Type": "application/json" },
          body: JSON.stringify({
            contents: [{ parts: [{ text: prompt }] }],
            // 2000 is not the answer length — the prompt caps that at 120
            // words. Gemini 3.x spends output budget on its own reasoning
            // first, so a 400-token cap returned a truncated half-draft
            // ("Draft 1:* Since you have already…") instead of prose.
            // thinkingConfig is rejected by this endpoint (400), so the
            // working lever is simply a budget big enough to think in.
            generationConfig: { temperature: 0.5, maxOutputTokens: 2000 },
          }),
        }
      );
      if (!res.ok) throw new Error(`Gemini ${res.status}`);
      const data = await res.json();
      const candidate = data.candidates?.[0];
      const text = (candidate?.content?.parts || [])
        .map((part) => part.text)
        .filter(Boolean)
        .join("")
        .trim();

      // Only replace the local plan with a COMPLETE answer. A run that hit
      // the token ceiling comes back mid-sentence, and a truncated paragraph
      // under a "written live" badge is worse than the deterministic plan
      // that is already on screen.
      const finished =
        !candidate?.finishReason || candidate.finishReason === "STOP";
      if (text && finished) {
        setResult({ ...base, source: "gemini", text });
      }
    } catch (err) {
      // Deliberately quiet: the local plan is already on screen and is a real
      // answer, not a fallback apology.
      console.warn("Planner: Gemini unavailable —", err.message);
    } finally {
      setBusy(false);
    }
  };

  return (
    <section className="lrn-planner" id="plan">
      <h2 className="lrn-h2">Plan my path</h2>
      <p className="lrn-lede">
        Tell me where you are. You'll get a real ordering out of the tracks
        below — not a generated syllabus of links I've never opened.
      </p>

      <div className="pl-row">
        <span className="pl-label">Where you are</span>
        <div className="pl-opts">
          {LEVELS.map((l) => (
            <button
              key={l.id}
              type="button"
              className={`pl-opt ${level === l.id ? "on" : ""}`}
              onClick={() => setLevel(l.id)}
            >
              <strong>{l.label}</strong>
              <em>{l.detail}</em>
            </button>
          ))}
        </div>
      </div>

      <div className="pl-row">
        <span className="pl-label">What you want to build</span>
        <div className="pl-opts">
          {allPaths().map((p) => (
            <button
              key={p.id}
              type="button"
              className={`pl-opt ${goal === p.id ? "on" : ""}`}
              onClick={() => setGoal(p.id)}
            >
              <strong>{p.label}</strong>
              <em>{p.kicker}</em>
            </button>
          ))}
        </div>
      </div>

      <div className="pl-row">
        <span className="pl-label">Time you actually have</span>
        <div className="pl-opts pace">
          {PACES.map((p) => (
            <button
              key={p.id}
              type="button"
              className={`pl-opt ${pace === p.id ? "on" : ""}`}
              onClick={() => setPace(p.id)}
            >
              <strong>{p.label}</strong>
            </button>
          ))}
        </div>
      </div>

      <div className="pl-row">
        <label className="pl-label" htmlFor="pl-detail">
          Anything specific? <span className="viz-muted">(optional)</span>
        </label>
        <input
          id="pl-detail"
          className="pl-input"
          placeholder="e.g. I have an interview in six weeks and I've never built an agent"
          value={detail}
          onChange={(e) => setDetail(e.target.value.slice(0, 200))}
        />
      </div>

      <button type="button" className="pl-go" onClick={run} disabled={busy}>
        {busy ? "Thinking…" : "Build my plan"}
      </button>

      {result && (
        <div className="pl-result" aria-live="polite">
          <span className={`pl-badge ${result.source}`}>
            {result.source === "gemini"
              ? "written live by Gemini, grounded in the tracks below"
              : "straight from the curriculum — no model involved"}
          </span>
          {/* The deterministic plan is on screen in a few milliseconds; the
              model takes ~10s because 3.x reasons before it writes. Say so,
              rather than letting the paragraph silently rewrite itself. */}
          {busy && result.source !== "gemini" && (
            <span className="pl-refining">
              Gemini is writing a longer version…
            </span>
          )}

          <p className="pl-text">
            {result.text
              .split(/(\*\*[^*]+\*\*)/g)
              .map((chunk, i) =>
                chunk.startsWith("**") && chunk.endsWith("**") ? (
                  <strong key={i}>{chunk.slice(2, -2)}</strong>
                ) : (
                  chunk
                )
              )}
          </p>

          <div className="pl-chain">
            {result.tracks.map((t, i) => (
              <React.Fragment key={t.id}>
                {i > 0 && <span className="pl-arrow">→</span>}
                <a
                  className="pl-pill"
                  href={`#track-${t.id}`}
                  style={{ "--c": t.accent }}
                >
                  {t.title}
                </a>
              </React.Fragment>
            ))}
          </div>
        </div>
      )}
    </section>
  );
}
